<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';

use App\Core\Auth;
use App\Core\Database;

Auth::requirePermission('competitors.view');
$pdo=Database::connection();
$error='';
$tableExists=static function(string $table)use($pdo):bool{try{$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:table');$q->execute(['table'=>$table]);return (int)$q->fetchColumn()>0;}catch(Throwable){return false;}};
$wdcReady=$tableExists('bdc_wdc_identities')&&$tableExists('bdc_wdc_registrations');
$q=trim((string)($_GET['q']??''));$style=(string)($_GET['style']??'');$entry=(string)($_GET['entry']??'');$level=(string)($_GET['level']??'');
$registrationRows=[];$counts=['identities'=>0,'entries'=>0,'shared'=>0,'missing_photo'=>0];

try{
    if($wdcReady){
        $where=["w.status='active'","r.status='registered'"];$params=[];
        if($q!==''){$where[]='(LOWER(w.display_name) LIKE LOWER(:name) OR LOWER(w.identity_code) LIKE LOWER(:code) OR LOWER(COALESCE(NULLIF(w.country,\'\'),c.country,\'\')) LIKE LOWER(:country) OR LOWER(r.category_name) LIKE LOWER(:category))';$like='%'.$q.'%';$params+=['name'=>$like,'code'=>$like,'country'=>$like,'category'=>$like];}
        if(in_array($style,['salsa','bachata','other'],true)){$where[]='r.dance_style=:style';$params['style']=$style;}
        if(in_array($entry,['solo','couple','duo','pro_am','team'],true)){$where[]='r.entry_type=:entry';$params['entry']=$entry;}
        if(in_array($level,['open','amateur','intermediate','pro_am','professional'],true)){$where[]='r.competition_level=:level';$params['level']=$level;}
        $sql="SELECT w.id wdc_identity_id,w.identity_code,w.display_name,w.entry_type,w.solo_competitor_id,COALESCE(NULLIF(w.country,''),c.country) country,COALESCE(NULLIF(w.photo_url,''),NULLIF(c.photo_url,'')) photo_url,c.instagram,c.gender,r.id registration_id,r.event_name,r.category_key,r.category_name,r.dance_style,r.competition_level FROM bdc_wdc_registrations r JOIN bdc_wdc_identities w ON w.id=r.wdc_identity_id LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id WHERE ".implode(' AND ',$where)." ORDER BY LOWER(w.display_name),w.id,LOWER(r.category_name),r.id";
        $stmt=$pdo->prepare($sql);$stmt->execute($params);$registrationRows=$stmt->fetchAll();
        $identities=[];$shared=[];$missing=[];
        foreach($registrationRows as $row){$id=(int)$row['wdc_identity_id'];$identities[$id]=true;if((int)$row['solo_competitor_id']>0)$shared[$id]=true;if(trim((string)$row['photo_url'])==='')$missing[$id]=true;}
        $counts=['identities'=>count($identities),'entries'=>count($registrationRows),'shared'=>count($shared),'missing_photo'=>count($missing)];
    }
}catch(Throwable $exception){$error='Some WDC participant data could not be loaded: '.$exception->getMessage();}

$label=static fn(?string $value):string=>ucwords(str_replace('_',' ',(string)$value));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Participants | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=487" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=505"></script><style>.summary-card{border:0;border-radius:16px}.summary-card strong{font-size:1.8rem}.dc-photo{width:58px;height:68px;object-fit:cover;border-radius:10px;border:1px solid #dce3ec}.dc-section{border:0;border-radius:18px}.table td,.table th{vertical-align:middle}.dc-actions{display:flex;gap:6px;flex-wrap:wrap}.dc-category{min-width:190px}@media(max-width:767px){.dc-actions{display:grid}.dc-actions .btn{width:100%}.dc-category{min-width:160px}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">BDC Dance Cup</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="workflow.php?workflow=automatic">Scoring</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></div></nav><main class="container-fluid py-4" style="max-width:1650px"><div class="mb-3"><h1 class="h3 mb-1">Dance Cup Participants</h1><p class="text-muted mb-0">Approved WDC identities and category registrations in one place.</p></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!$wdcReady):?><div class="alert alert-warning">WDC identities and registrations are not available yet.</div><?php endif;?><div class="row g-3 mb-4"><?php foreach(['WDC Identities'=>$counts['identities'],'Category Entries'=>$counts['entries'],'Shared Person Links'=>$counts['shared'],'Missing Photos'=>$counts['missing_photo']] as $title=>$value):?><div class="col-6 col-xl-3"><section class="card summary-card shadow-sm h-100"><div class="card-body"><span class="text-muted small"><?=e($title)?></span><strong class="d-block"><?=$value?></strong></div></section></div><?php endforeach;?></div>

<form class="card dc-section shadow-sm mb-4"><div class="card-body"><div class="row g-2 align-items-end"><div class="col-lg-5"><label class="form-label small">Search participants</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID, country or category"></div><?php foreach(['style'=>['Dance Style',[''=>'All styles','salsa'=>'Salsa','bachata'=>'Bachata','other'=>'Other']],'entry'=>['Entry Type',[''=>'All entry types','solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro Am','team'=>'Team']],'level'=>['Level',[''=>'All levels','open'=>'Open','amateur'=>'Amateur','intermediate'=>'Intermediate','pro_am'=>'Pro Am','professional'=>'Professional']]] as $name=>[$title,$options]):?><div class="col-6 col-lg"><label class="form-label small"><?=e($title)?></label><select class="form-select" name="<?=$name?>"><?php foreach($options as $value=>$text):?><option value="<?=e($value)?>" <?=($$name===$value)?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="col-12"><button class="btn btn-dark">Apply Filters</button> <a class="btn btn-outline-secondary" href="participants.php">Reset</a></div></div></div></form>

<section class="card dc-section shadow-sm"><div class="card-body d-flex justify-content-between gap-2 flex-wrap"><div><h2 class="h4 mb-1">Dance Participation</h2><p class="text-muted mb-0">Each approved WDC identity and category registration is shown once.</p></div><span class="badge text-bg-primary align-self-start"><?=count($registrationRows)?> shown</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Photo</th><th>WDC ID</th><th>Participant</th><th class="dc-category">Category</th><th>Country</th><th>Dance Style</th><th>Entry Type</th><th>Level</th><th>Profile Actions</th></tr></thead><tbody><?php foreach($registrationRows as $row):$wdcId=(int)$row['wdc_identity_id'];$personId=(int)$row['solo_competitor_id'];?><tr><td><img class="dc-photo" src="<?=e($row['photo_url']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><code><?=e($row['identity_code'])?></code></td><td><strong><?=e($row['display_name'])?></strong><?php if($row['instagram']):?><small class="d-block text-muted">@<?=e(ltrim((string)$row['instagram'],'@'))?></small><?php endif;?></td><td class="dc-category"><strong><?=e($row['category_name'])?></strong><small class="d-block text-muted"><?=e($row['event_name'])?></small></td><td><?=e($row['country']?:'—')?><?php if($row['gender']):?><small class="d-block text-muted"><?=e($label($row['gender']))?></small><?php endif;?></td><td><span class="badge text-bg-primary"><?=e($label($row['dance_style']))?></span></td><td><?=e($label($row['entry_type']))?></td><td><strong><?=e($label($row['competition_level']))?></strong></td><td><div class="dc-actions"><a class="btn btn-sm btn-dark" href="competitor-edit.php?id=<?=$wdcId?>">Edit WDC</a><?php if($personId):?><a class="btn btn-sm btn-outline-primary" href="../competitors/photo-adjust.php?id=<?=$personId?>&amp;return=<?=e(rawurlencode('../dance-cup/participants.php'))?>">Adjust Photo</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$registrationRows):?><tr><td colspan="9" class="text-center text-muted py-5">No WDC registrations match the selected filters.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
